"""Capture actual repaired CLI behavior and fuel trace at the original limit."""
from pathlib import Path
import hashlib,json,os,subprocess,time
ROOT=Path(__file__).resolve().parents[2];OUT=Path(__file__).resolve().parent;exe=ROOT.parent/'m12-case-followup-target/debug/suss';source=(OUT/'before-input.sus').read_text();cmd=[str(exe),'repl','--compile-fuel','4000000'];binary_hash=hashlib.sha256(exe.read_bytes()).hexdigest();start=time.time();r=subprocess.run(['systemd-run','--user','--scope','-p','MemoryMax=3G','--',*cmd],cwd=ROOT,env=os.environ|{'XDG_RUNTIME_DIR':'/run/user/1000','SUSS_MACRO_FUEL_TRACE':'1'},input=source,text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE);(OUT/'after.stdout').write_text(r.stdout);(OUT/'after.stderr').write_text(r.stderr);receipt={'source_head':subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip(),'command':cmd,'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'executable_sha256':binary_hash,'executable_unchanged':hashlib.sha256(exe.read_bytes()).hexdigest()==binary_hash,'exit_code':r.returncode,'seconds':time.time()-start,'has_error':'Error:' in r.stderr,'expected_final_value_present':r.stdout.splitlines()[-1:] == ['17']};(OUT/'after-command.json').write_text(json.dumps(receipt,indent=2)+'\n');print(receipt);assert r.returncode==0 and not receipt['has_error'] and receipt['expected_final_value_present'] and receipt['executable_unchanged']
